// Parse Launch: the Apify run webhook. Body: { play: <Signals record id>, resource: <Apify run> }.
// Nothing else is read from the payload; the Signals row carries the config. The resource object
// carries the run's dataset (the reviews). Reused verbatim from Handle Hiring Intent Signal.
const sd=$getWorkflowStaticData('global');
sd.runStartedAt=$now.toMillis();
const j=$input.first().json||{};
const q=j.query||{}; const b=j.body||{};
const pick=(k)=>{ const v=(b[k]!==undefined&&b[k]!=='')?b[k]:q[k]; return (v===undefined||v===null)?'':String(v).trim(); };
const res=b.resource||{};
const cfg={
  play: pick('play'),
  datasetId: String(res.defaultDatasetId||''),
  kvStoreId: String(res.defaultKeyValueStoreId||''),
  sender: pick('sender')||'webhook'
};
const missing=[];
if(!/^rec[A-Za-z0-9]{14}$/.test(cfg.play)) missing.push('play (Signals record id)');
if(!cfg.datasetId) missing.push('resource.defaultDatasetId');
cfg.config_ok=(missing.length===0);
cfg.missing=missing;
cfg.guard='launch';
return [{ json: cfg }];

// Parse Play: the Signals row (Hub, one row per signal) into the run's config. Typed fields,
// no grammar: Name, Client (link), Signal Type, Country, Max Employees, ICP. Target Table is
// retired (List Building 2.0, 2026-09-02): every signal writes the client's Companies table,
// resolved downstream from the Client link. A signal is the Signals link on the row, never a
// Tag: nothing here reads a Tag. Roles is read but not required: the reviews handler writes
// no Existing In Role (not on its register).
// The upstream node searches Signals with OR(RECORD_ID() = launch play id, {Signal Type} =
// 'trustpilot_reviews'), so a launch whose id went stale still resolves as long as exactly ONE
// trustpilot_reviews signal exists; ambiguity or no match stops the run before any paid call.
// The type names the DATASET SHAPE this handler's source-parse reads, never the topic: stars,
// topics, freshness are Apify task config (Operator ruling 2026-09-01).
// Country may be a comma list ("US, GB"): the company's country, never the reviewer's.
// Who gets MESSAGED is not config here or anywhere in this machine: relevance and the views
// on People decide that. This machine only lands company rows.
// Diff from the hiring handler: the fallback Signal Type string, the default event_type, Roles optional.
const launch=$('Parse Launch').first().json;
const rows=$input.all().map(i=>i.json).filter(r=>r&&(r.id||r.fields));
const norm=(r)=>({ id:r.id, f:(r.fields||r) });
const wanted=launch.play;
const all=rows.map(norm);
const missing=[];
let hit=all.find(r=>r.id===wanted);
let legacy=false;
if(!hit){
  const same=all.filter(r=>String(r.f['Signal Type']||'')==='trustpilot_reviews');
  if(same.length===1){ hit=same[0]; legacy=true; }
  else missing.push(same.length===0?'no Signals row found for launch id '+wanted:'launch id '+wanted+' unknown and '+same.length+' trustpilot_reviews signals exist (ambiguous); update the Apify webhook payload to the Signals record id');
}
const f=hit?hit.f:{};
const list=(s)=>String(s||'').split(',').map(x=>x.trim()).filter(Boolean);
const clientLink=Array.isArray(f['Client'])?f['Client'][0]:'';
const client=clientLink&&typeof clientLink==='object'?String(clientLink.id||''):String(clientLink||'');
const roles=list(f['Roles']);
const countries=list(f['Country']).map(c=>c.toUpperCase());
const country=countries.join(', ');
const maxEmployees=Number(f['Max Employees'])||0;
const icp=String(f['ICP']||'').trim();
if(hit){
  if(!client) missing.push('Client link on the Signals row');
  if(!country) missing.push('Country');
  if(!maxEmployees) missing.push('Max Employees');
  if(!icp) missing.push('ICP');
}
return [{ json: {
  play: launch.play, datasetId: launch.datasetId, kvStoreId: launch.kvStoreId, sender: launch.sender,
  play_name: f['Name']||'', signal_row: hit?hit.id:'', legacy_launch_id: legacy,
  client, event_type: String(f['Signal Type']||'trustpilot_reviews'),
  country, countries, max_headcount: maxEmployees, icp_text: icp,
  roles,
  config_ok: missing.length===0, missing, guard:'play'
}}];

const r=$input.first().json||{};
const f=r.fields||r;
const name=f['Client']||'';
return [{ json: {
  clientName: name,
  clientRecId: r.id||$('Parse Play').first().json.client||'',
  clientSlug: String(name).toLowerCase().replace(/[^a-z0-9]/g,''),
  slackChannel: f['Slack Channel ID']||'',
  base: f['Clayroots Base ID']||''
}}];

// Find Companies Table: the client base must already carry a table named "Companies"
// (case-insensitive) and the Signals mirror: the synced table whose name ends with "Signals".
// Nothing here ever creates a table; the scaffold is Onboard Client's job (List Building 2.0).
// The columns, DNC and the upsert are the helper Insert domains to Clayroots' business (Operator
// ruling 2026-09-02); this node only names the table for the log and describes the mirror the
// Signals link points at. Every refusal names what is missing.
//
// The mirror row is matched on the signal's NAME (Operator ruling 2026-09-02). The previous match
// was a synced "Record ID" column, which no client base carries: all four live mirrors were
// audited and none had it, so every hiring and reviews signal died at this node. Name and Client
// ride the sync on their own, so a mirror needs nothing configured, now or at onboarding.
//
// This node builds the mirror query and Resolve Mirror Row does the strict matching. The query is
// deliberately PERMISSIVE and the code deliberately STRICT, so that a near miss arrives as a
// candidate and gets refused by name instead of silently never being seen:
//   - TRIM() so a mirror row whose Name carries stray whitespace is still a candidate.
//   - LOWER() so a case variant is still a candidate. Airtable's "=" on text is case-SENSITIVE on
//     its own, probed live against a real mirror on 2026-09-02, so without LOWER() a case-only
//     mismatch would come back as "no row at all" and cost the Operator the real diagnosis.
//     Resolve Mirror Row then applies the case-SENSITIVE rule and names what it rejected.
// Because the code re-checks exactly, any divergence between Airtable's LOWER() and JS
// toLowerCase() on exotic input can only ever cause a refusal, never a wrong match.
// No field restriction is set on the query: the mirror's Companies link column is fat and grows,
// but only matching rows are ever returned, and a "fields" list naming Client would 422 on a
// mirror that does not carry it.
//
// Reused verbatim from Insert Hiring domains to Clayroots.
const base=$('Client Vars').first().json.base;
const cfg=$('Parse Play').first().json;
const r=$input.first().json||{};
const body=(r.body!==undefined)?r.body:r;
const tables=(body&&Array.isArray(body.tables))?body.tables:null;
if(!tables){ throw new Error('Could not read the table list for base '+base+': '+JSON.stringify(body).slice(0,200)+'. Nothing was spent or written.'); }
const t=tables.find(x=>String(x.name||'').trim().toLowerCase()==='companies');
if(!t){ throw new Error('Base '+base+' has no Companies table. Scaffold the base (Scaffold Client Base) first. Nothing was spent or written.'); }
const mirror=tables.find(x=>/signals$/i.test(String(x.name||'').trim()));
if(!mirror){ throw new Error('Base '+base+' has no Signals mirror (a synced table whose name ends with "Signals"). Sync the Hub Signals view into the client base first. Nothing was spent or written.'); }
const mirrorFields=new Set((mirror.fields||[]).map(x=>x.name));
if(!mirrorFields.has('Name')){ throw new Error('The Signals mirror '+mirror.name+' ('+mirror.id+') has no "Name" field, so a Hub signal cannot be resolved to a mirror row. Include Name in the synced Signals view first. Nothing was spent or written.'); }
const signalName=String(cfg.play_name||'').trim();
if(!signalName){ throw new Error('The Hub signal '+cfg.signal_row+' has no Name, so there is nothing to match against the Signals mirror '+mirror.name+' ('+mirror.id+') in base '+base+'. Name the Signals row first. Nothing was spent or written.'); }
const esc=signalName.toLowerCase().replace(/\\/g,'\\\\').replace(/'/g,"\\'");
return [{ json: {
  base, tableId:t.id, tableName:t.name,
  signalsTableId:mirror.id, signalsTableName:mirror.name,
  mirrorHasClient:mirrorFields.has('Client'),
  signalName,
  mirrorFilter:"LOWER(TRIM({Name})) = '"+esc+"'"
} }];

// Resolve Mirror Row: the client base's Signals mirror row this Hub signal maps to, resolved
// BEFORE any paid call (Operator ruling 2026-09-02). No row, no relation: refuse here, nothing
// spent, nothing written. Emits the table facts (Find Companies Table) plus the mirror row id
// Format Companies links to.
//
// Matched on the signal's NAME (Operator ruling 2026-09-02, replacing a synced "Record ID" column
// that no client base ever carried). Strictness is what makes name matching safe, and it is not
// optional: exactly one row survives, or the run stops here with a named error saying what it
// looked for and what it found. A silent wrong guess is the failure mode this check exists to
// remove, and it is the reason name matching was accepted at all.
//
//   - Exact, trimmed name. Never a contains, never a fuzzy match.
//   - CASE-SENSITIVE. The Hub row's Name and the mirror row's Name are the same string carried
//     across by Airtable's own sync; nobody retypes it in between. So a case difference does not
//     mean "same signal, spelled loosely", it means these are two different Hub rows, and
//     resolving one to the other would be exactly the silent wrong guess. Refusing costs a named
//     error the Operator fixes in seconds; guessing costs a paid run written against the wrong
//     signal. The upstream query wraps the name in LOWER() on purpose, so a case-variant row
//     arrives here as a candidate and gets refused out loud instead of never being seen.
//   - Scoped to the client whenever the mirror carries a Client column, so two clients' signals
//     sharing a name cannot collide. A blank Client is not evidence of another owner, so such a
//     row stays a candidate; a Client naming a different client is, and that row is dropped.
//
// Reused verbatim from the hiring door.
const cfg=$('Parse Play').first().json;
const t=$('Find Companies Table').first().json;
const clientName=String(($('Client Vars').first().json||{}).clientName||'').trim();
const want=String(t.signalName||cfg.play_name||'').trim();
const where='the Signals mirror '+(t.signalsTableName||t.signalsTableId)+' in base '+t.base;
const rows=$input.all().map(i=>i.json||{}).filter(j=>j&&j.id);
const fieldsOf=(j)=>(j.fields&&typeof j.fields==='object')?j.fields:j;
const nameOf=(j)=>String(fieldsOf(j)['Name']||'').trim();
const clientOf=(j)=>{ const c=fieldsOf(j)['Client']; return String(Array.isArray(c)?(c[0]||''):(c||'')).trim(); };
const exact=rows.filter(j=>nameOf(j)===want);
const scoped=(t.mirrorHasClient&&clientName)?exact.filter(j=>{ const c=clientOf(j); return !c||c===clientName; }):exact;
if(scoped.length!==1){
  const show=(j)=>'"'+nameOf(j)+'"'+(clientOf(j)?' ['+clientOf(j)+']':' [no Client]')+' ('+j.id+')';
  let found;
  if(scoped.length===0){
    found=rows.length===0
      ? 'the mirror returned no row at all'
      : 'the mirror returned '+rows.length+' near miss(es) that did not survive the exact, case-sensitive'+(t.mirrorHasClient&&clientName?', client-scoped':'')+' check: '+rows.map(show).join(', ');
  } else {
    found=scoped.length+' rows carry that exact name: '+scoped.map(show).join(', ');
  }
  throw new Error('Cannot resolve Hub signal "'+want+'" (row '+cfg.signal_row+', client '+(clientName||'unknown')+') to exactly one row in '+where+': '+found+'. Matching is on the exact trimmed Name, case-sensitive'+(t.mirrorHasClient?', scoped to the client':', unscoped because the mirror carries no Client column')+'. Fix the Signals sync or the duplicate name, then re-fire. Nothing was spent or written.');
}
return [{ json: Object.assign({}, t, { mirrorId: scoped[0].id, mirrorName: nameOf(scoped[0]) }) }];

// Filter & Qualify Reviews: N scraped Trustpilot rows in, ONE row per qualified company out,
// every drop counted by reason. The signal payload (negative-review count, freshest date, the
// quotes, the reply share, the trust score) rides on the company row so the writer can stamp
// it on the Companies row. _stats on the first row feeds Build Run Log.
//
// THE FRESH PIECE of this handler; everything downstream is the hiring handler reused.
//
// Source shape: blackfalcondata/trustpilot-reviews-scraper, reviews mode. Stars (1-2) and
// topics (customer_service) are filtered SERVER-SIDE in the Apify task config; the rating<=2
// check here is a belt, counted when it fires. includeCompanyInfo adds company-metadata rows
// (totalReviews, countryCode, contactEmail) to the same dataset; both row kinds are read,
// neither is required. Proven live 2026-08-27 on 10 big + 10 small DTC brands.
//
// Drops, in order: not negative (belt) · no domain · hosted platform · wrong country.
// The "already in table" line is gone (Operator ruling 2026-09-02): a company that signals
// again is updated in place and re-enters the queue. Notes against the hiring hard lines:
//   - Country: the COMPANY's country, against the Signals row's comma list ("US, GB"), read
//     only from a company-metadata row (countryCode). reviewerCountry is the REVIEWER's
//     country and never gates: who wrote the review is irrelevant (Operator 2026-09-01).
//     Unknown company country passes on purpose, mirroring the hiring rule; the watchlist
//     and the ICP sentence carry the geography where Trustpilot stays silent.
//   - Max Employees / headcount: Trustpilot carries no headcount. No gate here; BizData lands
//     Employees on the row and the Signals row's ICP sentence carries the size qualification.
//   - Staffing words / body-shop test: job-post pathologies, no review analog. Not rewritten.
//   - Duplicate: grouping by domain IS the dedupe; the counter stays for repeated
//     company-metadata rows.
const cfg=$('Parse Play').first().json;
let items=$('Get Scraped Reviews').all().map(i=>i.json);
if(items.length===1&&Array.isArray(items[0])) items=items[0];
items=items.filter(r=>r&&typeof r==='object');

// A company whose "website" lives on a free-hosting subdomain is not a company (hiring
// handler's fence, reused verbatim).
const HOSTED=['vercel.app','github.io','netlify.app','webflow.io','wixsite.com','carrd.co','notion.site','framer.website','framer.app','glitch.me','herokuapp.com','pages.dev','web.app','firebaseapp.com','squarespace.com','weebly.com','wordpress.com','godaddysites.com','mystrikingly.com','super.site'];
const isHosted=(d)=>HOSTED.some(h=>d===h||d.endsWith('.'+h));
const norm=(d)=>String(d||'').toLowerCase().replace('https://','').replace('http://','').replace('www.','').split('?')[0].split('#')[0].split('/')[0].trim();

// Split the dataset: review rows carry a rating; company-metadata rows carry totalReviews
// (or type 'company') and no rating.
const isCompanyRow=(r)=>(r.type==='company'||r.type==='companyInfo'||(r.rating===undefined&&(r.totalReviews!==undefined||r.trustScore!==undefined)));
const companyMeta={};
const reviews=[];
let metaRows=0;
for(const r of items){
  if(isCompanyRow(r)){ metaRows++; const d=norm(r.companyDomain||r.domain||r.website); if(d&&!companyMeta[d]) companyMeta[d]=r; continue; }
  if(r.rating!==undefined) reviews.push(r);
}

const drops={not_negative:0,no_domain:0,hosted_platform:0,country:0,duplicate:0};
const byDomain={};
for(const r of reviews){
  if(Number(r.rating)>2){ drops.not_negative++; continue; }
  const d=norm(r.companyDomain);
  if(!d){ drops.no_domain++; continue; }
  if(isHosted(d)){ drops.hosted_platform++; continue; }
  if(!byDomain[d]) byDomain[d]={ domain:d, name:String(r.companyName||'').trim(), reviews:[] };
  byDomain[d].reviews.push(r);
}

// Reviewers paste their own phone numbers and street addresses into rants; those quotes become
// table columns and copy variables, so PII is stripped before anything is written.
const stripPII=(s)=>String(s||'')
  .replace(/\+?\d[\d\s().-]{7,}\d/g,'[...]')
  .replace(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g,'[...]')
  .replace(/\b\d{1,5}\s+[A-Za-z][A-Za-z' ]*\s(?:street|st|avenue|ave|road|rd|lane|ln|drive|dr|boulevard|blvd|court|ct|way|place|pl)\b\.?/gi,'[...]');

const countries=(Array.isArray(cfg.countries)&&cfg.countries.length)?cfg.countries:String(cfg.country||'').split(',').map(x=>x.trim().toUpperCase()).filter(Boolean);
const out=[];
for(const d of Object.keys(byDomain)){
  const c=byDomain[d];
  const meta=companyMeta[d]||{};
  const country=String(meta.countryCode||meta.country||'').trim().toUpperCase();
  if(country&&countries.length&&!countries.includes(country)){ drops.country++; continue; }
  c.reviews.sort((a,b)=>String(b.publishedDate||'').localeCompare(String(a.publishedDate||'')));
  const latest=c.reviews[0]||{};
  const replied=c.reviews.filter(r=>r.hasCompanyReply===true).length;
  const clip=(s,n)=>stripPII(String(s||'').replace(/\s+/g,' ').trim()).slice(0,n);
  const quotes=c.reviews.slice(0,3).map(r=>'"'+clip(r.title,80)+'" - '+clip(r.text,220)).join('\n');
  const titles=c.reviews.slice(0,5).map(r=>clip(r.title,80)).filter(Boolean).join(' · ');
  const trust=c.reviews.map(r=>r.companyTrustScore).find(v=>v!==undefined&&v!==null);
  const trustScore=(trust!==undefined&&trust!==null)?Number(trust):(meta.trustScore!==undefined?Number(meta.trustScore):null);
  out.push({ json: {
    domain: d,
    company: c.name||String(meta.companyName||'').trim(),
    headcount: 0,
    country: country,
    company_website: 'https://'+d,
    signal: {
      count: c.reviews.length,
      latest_date: latest.publishedDate||'',
      latest_url: latest.reviewUrl||'',
      titles, quotes,
      replied, replied_label: replied+'/'+c.reviews.length,
      trust_score: trustScore,
      total_reviews: (meta.totalReviews!==undefined&&meta.totalReviews!==null)?Number(meta.totalReviews):null,
      trustpilot_url: 'https://www.trustpilot.com/review/'+d,
      contact_email: String(meta.contactEmail||'').trim()
    }
  }});
}

const stats={ reviews_in: reviews.length, meta_rows: metaRows, companies_in: Object.keys(byDomain).length, qualified: out.length, drops };
if(!out.length) return [{ json: { _empty:true, _stats:stats } }];
out[0].json._stats=stats;
return out;

// Company Facts: reads BizData for every company that passed the hard lines, drops the ones
// DiscoLike reports closed, and hands the survivors to the ICP check as ONE list (one task,
// per DiscoLike's own rule). Industry groups are recorded on the row later, never a verdict.
// Emits one item: { domains, icp_text, companies:{domain -> {company row, biz}} }.
// Reused from Handle Hiring Intent Signal; the only diff is the source node's name.
const cfg=$('Parse Play').first().json;
const parse=(b)=>{ if(typeof b!=='string') return b; try{ return JSON.parse(b); }catch(e){ return null; } };
const rows=$('Filter & Qualify Reviews').all().map(i=>i.json).filter(c=>c&&c.domain);
let bizItems=[]; try{ bizItems=$('DiscoLike BizData').all(); }catch(e){}
const stats={ called:0, matched:0, unknown:0, closed:0, errors:0, failed:[] };
const companies={};
const closed=[];
rows.forEach((c,i)=>{
  const it=bizItems[i]; const j=(it&&it.json)||{};
  const status=Number(j.statusCode)||0; const b=parse(j.body===undefined?null:j.body);
  stats.called++;
  let biz=null;
  if(status>=200&&status<300&&b&&typeof b==='object'&&(b.domain||b.name)){ biz=b; stats.matched++; }
  else if(status===204||status===404){ stats.unknown++; }
  else { stats.errors++; stats.failed.push({ tier:'BizData', name:c.domain, reason:'HTTP '+status+' '+String((b&&(b.detail||b.error||b.message))||'').slice(0,120) }); }
  if(biz&&biz.status&&biz.status.status==='closed'&&Number(biz.status.confidence||0)>=0.8){ stats.closed++; closed.push(c.domain); return; }
  companies[c.domain]={ company:c, biz };
});
const domains=Object.keys(companies);
const out={ domains, icp_text: cfg.icp_text, companies, closed, _stats: stats };
return [{ json: out }];

// Prep Poll: reads the task id the ICP check returned and starts the poll loop.
// No task id means the check never started: the loop is skipped and every company is
// reported as an ICP error downstream (never passed through as a yes).
// Reused verbatim from Handle Hiring Intent Signal.
const j=$input.first().json||{};
const status=Number(j.statusCode)||0;
let b=j.body; if(typeof b==='string'){ try{ b=JSON.parse(b); }catch(e){ b=null; } }
const taskId=b&&b.task_id?String(b.task_id):'';
if(!taskId) return [{ json: { task_id:'', done:true, results:null, error:'validate/icp HTTP '+status+' '+String((b&&(b.detail||b.error||b.message))||'no task_id').slice(0,120) } }];
return [{ json: { task_id: taskId, done:false, results:null, error:'' } }];

// Poll Check: one pass of the ICP poll loop. Reads the discogen status; done when the task
// completed or failed, or after 20 passes (5 minutes at 15 s), which is reported as an error.
// Reused verbatim from Handle Hiring Intent Signal.
const j=$input.first().json||{};
const status=Number(j.statusCode)||0;
let b=j.body; if(typeof b==='string'){ try{ b=JSON.parse(b); }catch(e){ b=null; } }
const taskId=String(($('Prep Poll').first().json||{}).task_id||'');
const pass=Number($runIndex)||0;
const st=b&&b.status?String(b.status):'';
if(st==='completed') return [{ json: { task_id:taskId, done:true, results:(b.results||{}), error:'', passes:pass+1 } }];
if(st==='failed'||st==='error'||status>=400) return [{ json: { task_id:taskId, done:true, results:null, error:'discogen '+(st||('HTTP '+status))+' '+String((b&&(b.error||b.detail||b.message))||'').slice(0,120), passes:pass+1 } }];
if(pass+1>=20) return [{ json: { task_id:taskId, done:true, results:null, error:'ICP check timed out after '+(pass+1)+' polls', passes:pass+1 } }];
return [{ json: { task_id:taskId, done:false, results:null, error:'', passes:pass+1 } }];

// Apply ICP: a company the check called `yes` or `partial` goes on (Operator ruling 2026-08-23:
// partial stays in). `no` and missing verdicts are dropped with their reason kept for the run log.
// A check that never completed rejects everything and is logged as an error: no company is ever
// passed through on a missing verdict.
// One row per kept company: { domain, company, biz, icp_reason, icp_confidence }.
// Reused verbatim from Handle Hiring Intent Signal.
const poll=$input.first().json||{};
const facts=$('Company Facts').first().json||{};
const companies=facts.companies||{};
const stats={ checked:0, yes:0, partial:0, no:0, missing:0, error:poll.error||'', rejected:[] };
const out=[];
if(poll.error||!poll.results){
  stats.error=poll.error||'no results';
  return [{ json: { _empty:true, _stats:stats } }];
}
const res=poll.results;
for(const d of Object.keys(companies)){
  const r=res[d]||res[d.replace(/^www\./,'')]||null;
  stats.checked++;
  if(!r){ stats.missing++; stats.rejected.push({ domain:d, fit:'missing', reason:'no verdict returned' }); continue; }
  const fit=String(r.Fit||r.fit||'').toLowerCase();
  const reason=String(r.Reasoning||r.reasoning||'').slice(0,200);
  const conf=String(r.Confidence||r.confidence||'');
  if(fit==='yes'||fit==='partial'){ if(fit==='yes') stats.yes++; else stats.partial++; out.push({ json: { domain:d, company:companies[d].company, biz:companies[d].biz, icp_reason:(fit==='partial'?'PARTIAL: ':'')+reason, icp_confidence:conf } }); }
  else { stats.no++; stats.rejected.push({ domain:d, fit:fit||'?', reason }); }
}
if(!out.length) return [{ json: { _empty:true, _stats:stats } }];
out[0].json._stats=stats;
return out;

// Build Run Log: the one row this run writes, per the logging standard. Status computed from
// failed[], skips separated (hard lines, closed, ICP rejects with reasons, DNC from the helper's
// counters, no domain), the Description is the whole funnel. Every node reference is guarded: a
// branch that never ran reads as 0. Records Out is what the helper Insert domains to Clayroots
// landed; the Waterfall Contacts hand-off is stated when it fired.
// Reused from Insert Hiring domains to Clayroots; diffs: the Automation name, the source-parse
// node name and its stats keys (reviews in place of jobs), the drop-line labels, no in-role line.
const sd=$getWorkflowStaticData('global'); const rs=sd.runStartedAt||0;
let cfg={}; try{ cfg=$('Parse Play').first().json||{}; }catch(e){ try{ cfg=$('Parse Launch').first().json||{}; }catch(e2){} }
let base=''; try{ base=$('Client Vars').first().json.base||''; }catch(e){}
let tbl={}; try{ tbl=$('Find Companies Table').first().json||{}; }catch(e){}
const nf=(x)=>Number(x||0).toLocaleString('en-US');
const failed=[]; const skips=[];

let fq={ reviews_in:0, meta_rows:0, companies_in:0, qualified:0, drops:{} };
try{ const s=$('Filter & Qualify Reviews').first().json._stats; if(s) fq=s; }catch(e){}
const d=fq.drops||{};
const dropLine=['not negative (belt) '+nf(d.not_negative),'no domain '+nf(d.no_domain),'hosted platform '+nf(d.hosted_platform),'wrong country '+nf(d.country),'duplicate '+nf(d.duplicate)].join(' · ');
const hardDropped=Math.max(0,(fq.companies_in||0)-(fq.qualified||0));

let bz={ called:0, matched:0, unknown:0, closed:0, errors:0, failed:[] }; let closedList=[];
try{ const f=$('Company Facts').first().json; if(f&&f._stats) bz=f._stats; closedList=(f&&f.closed)||[]; }catch(e){}
for(const f of (bz.failed||[])) failed.push(f);

let icp={ checked:0, yes:0, partial:0, no:0, missing:0, error:'', rejected:[] }; let polls=0;
try{ const s=$('Apply ICP').first().json._stats; if(s) icp=s; }catch(e){}
try{ polls=Number($('Poll Check').last().json.passes)||0; }catch(e){}
if(icp.error) failed.push({ tier:'ICP check', name:'task', reason:icp.error });

let fm={ icp:0, no_domain:0, new:0, existing:0, kept:0, failed:[] };
try{ const s=$('Format Companies').first().json._stats; if(s) fm=s; }catch(e){}
for(const f of (fm.failed||[])) failed.push(f);

// The helper's counters: the only truth about what landed. Absent when nothing was formatted.
let hp=null; try{ hp=$('Read Counters').first().json||null; }catch(e){}
const landed=hp?Number(hp.landed||0):0;
for(const f of ((hp&&hp.failed)||[])) failed.push(f);
if(hp&&fm.kept&&!landed&&!(hp.failed||[]).length&&!hp.dnc) failed.push({ tier:'Insert domains', name:nf(fm.kept)+' row(s)', reason:'formatted but the helper reported nothing landed' });

let waterfall=false; try{ waterfall=!!$('Waterfall Call').first().json; }catch(e){}

if(hardDropped||d.not_negative||d.no_domain||d.hosted_platform) skips.push(nf(hardDropped)+' companies failed the hard lines (review rows: '+dropLine+')');
if(bz.closed) skips.push(nf(bz.closed)+' reported closed by BizData'+(closedList.length?' ('+closedList.join(', ')+')':''));
if((icp.no||0)+(icp.missing||0)) skips.push(nf((icp.no||0)+(icp.missing||0))+' failed the ICP check');
if(hp&&hp.dnc) skips.push(nf(hp.dnc)+' on the DNC table (helper)');
if(fm.no_domain) skips.push(nf(fm.no_domain)+' no domain');

const errs=failed.length;
const status=errs?'Succeeded with errors':'Succeeded';
const rejLines=(icp.rejected||[]).slice(0,10).map(r=>'- '+r.domain+' ('+r.fit+'): '+r.reason);
const helperLine=hp?('created '+nf(hp.created)+' · updated '+nf(hp.updated)+' · DNC skipped '+nf(hp.dnc)+' · landed '+nf(landed)):'not called (nothing to land)';
const lines=[
  '**'+nf(landed)+' companies landed in '+(tbl.tableName||'Companies')+' via Insert domains to Clayroots ('+nf(fm.new)+' new, '+nf(fm.existing)+' signalled again) from '+nf(fq.reviews_in)+' review rows, '+errs+' error'+(errs===1?'':'s')+'**',
  '',
  '**Signal:** '+(cfg.play_name||cfg.play||'')+(cfg.legacy_launch_id?' (legacy launch id, update the Apify webhook to the Signals record id)':'')+' · **Type:** '+(cfg.event_type||'')+' · **Table:** '+(tbl.tableName||'Companies')+(tbl.tableId?' ('+tbl.tableId+')':'')+' in '+(base||''),
  '',
  '**Funnel**',
  '- **Review rows scraped:** '+nf(fq.reviews_in)+' at '+nf(fq.companies_in)+' companies'+(fq.meta_rows?' (+'+nf(fq.meta_rows)+' company-metadata rows)':''),
  '- **Past the hard lines:** '+nf(fq.qualified),
  '- **BizData:** matched '+nf(bz.matched)+' · unknown '+nf(bz.unknown)+' · closed '+nf(bz.closed)+' · errors '+nf(bz.errors),
  '- **ICP check:** '+nf(icp.checked)+' checked in '+nf(polls)+' poll'+(polls===1?'':'s')+' · yes '+nf(icp.yes)+' · partial (kept) '+nf(icp.partial)+' · no '+nf(icp.no)+(icp.missing?' · no verdict '+nf(icp.missing):''),
  '- **Rows formatted:** '+nf(fm.kept)+' ('+nf(fm.new)+' not yet in Companies, '+nf(fm.existing)+' existing, Signals unioned)',
  '- **Insert domains to Clayroots:** '+helperLine,
  '',
  '**Contacts:** '+(waterfall?'Waterfall Contacts fired as a sub-workflow (Companies · Not Sourced · ContaGen, Supersoniq, AI-Ark · cap 5,000); its own run-log row carries the pull.':'Waterfall Contacts not fired (nothing landed).')+' **Enrollment:** the deploy doors feed campaigns from the views (Signal link on Campaigns).'
];
if(rejLines.length) lines.push('','**ICP rejected ('+nf((icp.rejected||[]).length)+')**\n'+rejLines.join('\n')+((icp.rejected||[]).length>10?'\n- ...and '+((icp.rejected||[]).length-10)+' more':''));
if(failed.length) lines.push('','**FAILED ('+failed.length+')**\n'+failed.slice(0,8).map(f=>'- '+f.tier+' · '+(f.name||'?')+': '+(f.reason||'')).join('\n')+(failed.length>8?'\n- ...and '+(failed.length-8)+' more':''));
if(skips.length) lines.push('','**Skipped**\n'+skips.map(s=>'- '+s).join('\n'));
const row={
 'Automation':'Insert Reviews domains to Clayroots',
 'Status':status,
 'Run at': $now.toISO(),
 'Records In': fq.reviews_in||0,
 'Records Out': landed,
 'Errors': errs,
 'Target': (tbl.tableName||'Companies')+(tbl.tableId?' ('+tbl.tableId+')':''),
 'Trigger':'webhook',
 'Execution ID': String($execution.id),
 'Execution Link': 'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id,
 'Duration s': Math.round(($now.toMillis() - (rs||$now.toMillis()))/1000),
 'Description': lines.join('\n')
};
if(cfg.client) row['Client']=[cfg.client];
return [{json:row}];

// A guard tripped before any paid call: the launch payload, the Signals row, or the client row
// is missing something. One error, the row says exactly what. 'Failed' is the Error Logger's
// word for a crash; a guard trip is Succeeded with errors.
// Reused from Insert Hiring domains to Clayroots; diffs: the Automation name and the fix-it text.
let g={};
try{ const p=$('Parse Play').first().json; if(p&&p.config_ok===false) g=p; }catch(e){}
if(!g.guard){ try{ const l=$('Parse Launch').first().json; if(l&&l.config_ok===false) g=l; }catch(e){} }
let baseMissing=false; if(!g.guard){ try{ const c=$('Client Vars').first().json; if(c&&!c.base){ baseMissing=true; g=Object.assign({},$('Parse Play').first().json,{guard:'client'}); } }catch(e){} }
const what=g.guard==='launch'?'Apify webhook payload':(g.guard==='play'?'Signals row '+(g.play||''):'client row '+(g.client||''));
const missing=baseMissing?'Clayroots Base ID on the Hub Clients row':((g.missing||[]).join(', ')||'unknown');
const row={
 'Automation':'Insert Reviews domains to Clayroots',
 'Status':'Succeeded with errors',
 'Run at': $now.toISO(),
 'Records In': 0,
 'Records Out': 0,
 'Errors': 1,
 'Target': 'Companies',
 'Trigger':'webhook',
 'Execution ID': String($execution.id),
 'Execution Link': 'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id,
 'Description': '**Guard tripped before any paid call, 1 error**\n\n**Where:** '+what+'\n\n**Missing / unreadable:** '+missing+'\n\nThe Signals row needs: Client link (its Clients row carries the Clayroots Base ID), Country, Max Employees, ICP. The Apify payload needs {play: <Signals record id>, resource}. Fix and rerun.'
};
if(g.client) row['Client']=[g.client];
return [{json:row}];

// Format Companies: one Companies row per ICP-approved company, in the register's shape plus the
// Reviews group (the 9 Review / Trustpilot columns), for the helper Insert domains to Clayroots
// (Operator ruling 2026-09-02). The helper owns Check Columns, DNC, Clean Fields and the upsert on
// Domain, so nothing here filters on the table's columns: every group key is emitted and a base
// without the Reviews group is refused by the helper, loudly, nothing written.
// The signal is a relation: `Signals` links the row to the mirror row Resolve Mirror Row found,
// unioned with the links the row already holds (Read Existing Signals, one small read by Domain,
// kept because the helper returns counters, not rows). `Signal At` is now, `ICP Reason` the
// verdict, the Review / Trustpilot payload the event (latest event wins).
// Domain Source rides in _meta (Attach Meta), never on the row. No Tag: a signal is the link.
// Never write null: a payload value the run does not have is omitted, never cleared; on an
// existing row an empty core value is omitted too (a signal never blanks what a landing door
// wrote). _stats on row 0 feeds Build Run Log; zero rows emit one {_empty} placeholder so the
// gate reaches the close.
// Reused from Insert Hiring domains to Clayroots; the diffs: no Existing In Role, the payload columns.
const t=$('Resolve Mirror Row').first().json;
const mirrorId=t.mirrorId;
const nowIso=new Date().toISOString();
const norm=(d)=>String(d||'').trim().toLowerCase().replace(/^https?:\/\//,'').replace(/^www\./,'').replace(/\/.*$/,'');
const BANDS=['1-10','11-50','51-200','201-500','501-1000','1001-5000','5001-10000','10001+'];
const band=(v)=>{ const s=String(v==null?'':v).trim(); if(!s) return ''; if(BANDS.indexOf(s)>-1) return s; const n=Number(s.replace(/[,\s]/g,'')); if(!isFinite(n)||n<=0) return ''; if(n<=10) return '1-10'; if(n<=50) return '11-50'; if(n<=200) return '51-200'; if(n<=500) return '201-500'; if(n<=1000) return '501-1000'; if(n<=5000) return '1001-5000'; if(n<=10000) return '5001-10000'; return '10001+'; };
const join=(a)=>Array.isArray(a)?a.filter(Boolean).map(String).join(', '):(a==null?'':String(a));
const kv=(o)=>o&&typeof o==='object'&&!Array.isArray(o)?Object.entries(o).map(([k,v])=>k+':'+(typeof v==='number'?v.toFixed(2):v)).join(', '):join(o);
const keys=(o)=>o&&typeof o==='object'&&!Array.isArray(o)?Object.keys(o).join(', '):join(o);
const PAYLOAD=new Set(['Review Count','Review Latest','Review Link','Review Titles','Review Quotes','Review Replied','Trustpilot Rating','Trustpilot Reviews Total','Trustpilot URL']);
const stats={ icp:0, no_domain:0, new:0, existing:0, kept:0, failed:[] };

// Rows already in Companies for the signalled domains: their Signals links are unioned, never replaced.
const existing={};
try{ for(const it of $('Read Existing Signals').all()){ const j=it.json||{}; const f=j.fields||{}; const d=norm(f.Domain); if(j.id&&d) existing[d]={ id:j.id, signals:(Array.isArray(f.Signals)?f.Signals:[]).map(x=>(x&&typeof x==='object')?x.id:x).filter(Boolean) }; } }catch(e){}

const icpRows=$('Apply ICP').all().map(i=>i.json).filter(c=>c&&c.domain);
const out=[];
for(const e of icpRows){
  stats.icp++;
  const d=norm(e.domain); if(!d){ stats.no_domain++; continue; }
  const c=e.company||{}; const b=e.biz||null; const s=c.signal||{}; const addr=(b&&b.address)||{};
  const ex=existing[d]||null;
  const signals=Array.from(new Set([].concat(ex?ex.signals:[], [mirrorId])));
  const row={
    'Domain': d,
    'Company': String(c.company||(b&&b.name)||'').trim(),
    'Country': String(addr.country||c.country||''),
    'Employees': band((b&&b.employees)||c.headcount),
    'Signals': signals,
    'Signal At': nowIso,
    'ICP Reason': e.icp_reason||''
  };
  if(b){ Object.assign(row, {
    'Description': String(b.description||''),
    'Industry Groups': kv(b.industry_groups),
    'Business Model': kv(b.business_model),
    'Revenue Range': String(b.revenue_range||''),
    'Keywords': keys(b.keywords),
    'State': String(addr.state||''), 'City': String(addr.city||''), 'Street': String(addr.street||''), 'Zip': String(addr.zip||''),
    'Phones': join(b.phones), 'Public Emails': join(b.public_emails), 'public_emails_clean': '',
    'Social URLs': join(b.social_urls),
    'MX Provider': String(b.mx_provider||''), 'Redirect Domain': String(b.redirect_domain||'')
  }); }
  Object.assign(row, {
    'Review Count': s.count||0, 'Review Latest': s.latest_date||'', 'Review Link': s.latest_url||'',
    'Review Titles': s.titles||'', 'Review Quotes': s.quotes||'', 'Review Replied': s.replied_label||'',
    'Trustpilot Rating': s.trust_score, 'Trustpilot Reviews Total': s.total_reviews,
    'Trustpilot URL': s.trustpilot_url||''
  });
  // Never null. Empty payload values omitted everywhere; empty core values omitted on existing rows.
  for(const k of Object.keys(row)){ const v=row[k]; if(v==null||(v===''&&(ex||PAYLOAD.has(k)))) delete row[k]; }
  if(ex&&row['Public Emails']!==undefined) row['public_emails_clean']='';
  if(ex) stats.existing++; else stats.new++;
  out.push({ json: row }); stats.kept++;
}
if(!out.length) return [{ json: { _empty:true, _stats:stats } }];
out[0].json._stats=stats;
return out;

// Attach Meta: the call shape the helper Insert domains to Clayroots reads. The rows go through
// as formatted, minus the run's own carriers (_stats and _empty stay behind for Build Run Log),
// and the first item carries _meta {base, clientRecId, tag, domainSource, allowNew}: no Tag (a
// signal is the Signals link, never a Tag), Domain Source = Signal, allowNew false (the Review
// columns are register extras; nothing outside the register may be created, so a base without
// the Reviews group is refused by the helper).
// Reused verbatim from Insert Hiring domains to Clayroots.
const cv=$('Client Vars').first().json;
const rows=$input.all().map(i=>i.json).filter(j=>j&&!j._empty);
const out=rows.map(j=>{ const r={}; for(const k of Object.keys(j)){ if(!k.startsWith('_')) r[k]=j[k]; } return { json:r }; });
if(!out.length) return [{ json:{ _empty:true } }];
out[0].json._meta={ base: cv.base, clientRecId: cv.clientRecId, tag:'', domainSource:'Signal', allowNew:false };
return out;

// Read Counters: the one counters item the helper Insert domains to Clayroots returns, read into
// one shape for the Any Landed? gate and Build Run Log. The helper's key names are read by alias
// until its contract lands (created / updated / upserted, dnc, in, failed[] or an errors count);
// landed falls back to created + updated. A Check Columns refusal never reaches here: the helper
// throws and the run crashes into the Error Logger with nothing written. Never throws itself: an
// unreadable item reads as zero landed and one failure, so the run still closes its row.
// Reused verbatim from Insert Hiring domains to Clayroots.
const j=$input.first().json||{};
const num=(...ks)=>{ for(const k of ks){ const v=j[k]; if(v!==undefined&&v!==null&&v!==''){ const n=Number(v); if(isFinite(n)) return n; } } return null; };
const created=num('created','new','inserted')||0;
const updated=num('updated','existing')||0;
let landed=num('upserted','landed','written','out','rows_out','records_out'); if(landed===null) landed=created+updated;
const dnc=num('dnc','dnc_skipped','skipped_dnc','suppressed')||0;
const rowsIn=num('in','rows_in','received','records_in')||0;
let failed=[];
if(Array.isArray(j.failed)) failed=j.failed.map(f=>(f&&typeof f==='object')?Object.assign({ tier:'Insert domains' }, f):{ tier:'Insert domains', name:'', reason:String(f) });
else { const e=num('errors','failed'); if(e) failed=[{ tier:'Insert domains', name:e+' row(s)', reason:'reported by the helper, no detail' }]; }
if(!Object.keys(j).length) failed.push({ tier:'Insert domains', name:'counters', reason:'the helper returned no counters item' });
return [{ json:{ rowsIn, created, updated, landed, dnc, failed, counters:j } }];

// Waterfall Call: the one event item Waterfall Contacts reads at its Sub Trigger (Event Row):
// the same keys as a launch row. Client = the Hub Clients record, Table Companies, View
// "Not Sourced", Max companies 5000 as the spend cap.
//
// Tiers is "AI-Ark", the intent path (Operator ruling 2026-09-02). This door has no launch row to
// read a mode off, and the intent lane is deliberately AI-Ark only: a flat five people per company
// and the buyer seniorities only, not the full waterfall's wide net. Departments and Roles stay
// empty on purpose: nothing about who gets MESSAGED is configured in this machine, the relevance
// formula and the views on People do all the cutting. The Signals row's Roles field is the
// signal's own intent, not a contact filter, and is deliberately not read here.
//
// Reached only after at least one company landed; the sub-workflow runs on its own
// (waitForSubWorkflow false) and writes its own run-log row.
// Reused verbatim from Insert Hiring domains to Clayroots.
const cv=$('Client Vars').first().json;
return [{ json:{ Client:[cv.clientRecId], Table:'Companies', View:'Not Sourced', Tiers:'AI-Ark', Departments:[], Roles:[], 'Max companies':5000 } }];
